initJs:
function(container, apiUrl, tables) {
  let currentProducts = [];
  let stores = [];
  let categories = [];
  let predictions = [];
  let orders = [];

  // テーブルインデックス
  const STORE_TABLE = 1;
  const PRODUCT_TABLE = 2;
  const PREDICTION_TABLE = 9;
  const ORDER_TABLE = 10;

  // 商品テーブル再描画関数
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; padding: 2rem; color: var(--text-muted);">該当する商品がありません</td></tr>';
      updatePredictionSummary([]);
      return;
    }

    tbody.innerHTML = products.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID) || {};
      const currentStock = Math.floor(Math.random() * 100) + 10; // 模擬在庫データ
      const predictedDemand = prediction.予測数量 || Math.floor(Math.random() * 50) + 5;
      const recommendedOrder = prediction.推奨発注数量 || Math.max(0, predictedDemand - currentStock);

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${currentStock}</td>
          <td>${predictedDemand}</td>
          <td>${recommendedOrder}</td>
          <td>
            <div style="display: flex; align-items: center; gap: 0.5rem;">
              <button class="action-btn secondary adjust-btn" data-action="decrease" data-product-id="${product.商品ID}">-</button>
              <input type="number" class="input order-quantity" data-product-id="${product.商品ID}" 
                     value="${recommendedOrder}" min="0" style="width: 80px; text-align: center;">
              <button class="action-btn secondary adjust-btn" data-action="increase" data-product-id="${product.商品ID}">+</button>
            </div>
          </td>
          <td>
            <input type="text" class="input order-reason" data-product-id="${product.商品ID}" 
                   placeholder="発注理由" style="width: 150px;">
          </td>
          <td>
            <button class="action-btn order-btn" data-product-id="${product.商品ID}">発注</button>
          </td>
        </tr>
      `;
    }).join('');

    updatePredictionSummary(products);
  }

  // 需要予測サマリー更新
  function updatePredictionSummary(products) {
    let totalPredicted = 0;
    let totalRecommended = 0;
    let totalStock = 0;

    products.forEach(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID) || {};
      const currentStock = Math.floor(Math.random() * 100) + 10;
      const predictedDemand = prediction.予測数量 || Math.floor(Math.random() * 50) + 5;
      const recommendedOrder = prediction.推奨発注数量 || Math.max(0, predictedDemand - currentStock);

      totalPredicted += predictedDemand;
      totalRecommended += recommendedOrder;
      totalStock += currentStock;
    });

    container.querySelector('#total-predicted').textContent = totalPredicted.toLocaleString();
    container.querySelector('#total-recommended').textContent = totalRecommended.toLocaleString();
    container.querySelector('#total-stock').textContent = totalStock.toLocaleString();
  }

  // 店舗・カテゴリドロップダウン初期化
  async function initDropdowns() {
    try {
      stores = await window.aivicApi.list(STORE_TABLE) || [];
      const products = await window.aivicApi.list(PRODUCT_TABLE) || [];

      const storeSelect = container.querySelector('#select-store');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.filter(s => s.有効フラグ).map(store => 
          `<option value="${store.店舗ID}">${store.店舗名}</option>`
        ).join('');

      // カテゴリは商品から抽出（実際の実装では商品カテゴリマスタを使用）
      const uniqueCategories = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];
      const categorySelect = container.querySelector('#select-category');
      categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>' +
        uniqueCategories.map(cat => 
          `<option value="${cat}">カテゴリ${cat.slice(-4)}</option>`
        ).join('');

    } catch (error) {
      console.error('ドロップダウン初期化エラー:', error);
    }
  }

  // 検索・フィルタリング
  async function searchProducts() {
    const storeId = container.querySelector('#select-store').value;
    const categoryId = container.querySelector('#select-category').value;
    const dateStart = container.querySelector('#input-date-start').value;
    const dateEnd = container.querySelector('#input-date-end').value;
    const searchKeyword = container.querySelector('#input-search').value.toLowerCase();

    // 日付バリデーション
    if (dateStart && dateEnd && new Date(dateStart) > new Date(dateEnd)) {
      alert('終了日は開始日以降の日付を入力してください');
      return;
    }

    if (!storeId) {
      renderProducts([]);
      return;
    }

    try {
      let products = await window.aivicApi.list(PRODUCT_TABLE) || [];
      predictions = await window.aivicApi.list(PREDICTION_TABLE) || [];
      orders = await window.aivicApi.list(ORDER_TABLE) || [];

      // フィルタリング
      products = products.filter(product => {
        if (!product.有効フラグ) return false;
        if (categoryId && product.商品カテゴリID !== categoryId) return false;
        if (searchKeyword && !product.商品名?.toLowerCase().includes(searchKeyword)) return false;
        return true;
      });

      // 発注日付範囲でのフィルタリング（発注履歴がある商品）
      if (dateStart || dateEnd) {
        const filteredOrders = orders.filter(order => {
          const orderDate = new Date(order.発注日);
          if (dateStart && orderDate < new Date(dateStart)) return false;
          if (dateEnd && orderDate > new Date(dateEnd)) return false;
          return true;
        });
        const orderedProductIds = [...new Set(filteredOrders.map(o => o.商品ID))];
        products = products.filter(p => orderedProductIds.includes(p.商品ID));
      }

      currentProducts = products;
      renderProducts(products);

    } catch (error) {
      console.error('検索エラー:', error);
      renderProducts([]);
    }
  }

  // 発注量調整
  function adjustOrderQuantity(productId, action) {
    const input = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);
    if (!input) return;

    let currentValue = parseInt(input.value) || 0;
    if (action === 'increase') {
      currentValue += 1;
    } else if (action === 'decrease' && currentValue > 0) {
      currentValue -= 1;
    }
    input.value = currentValue;
  }

  // 個別発注処理
  async function processOrder(productId) {
    const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);
    const reasonInput = container.querySelector(`input.order-reason[data-product-id="${productId}"]`);
    const storeId = container.querySelector('#select-store').value;

    const quantity = parseInt(quantityInput?.value) || 0;
    const reason = reasonInput?.value || '';

    // バリデーション
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    if (quantity <= 0) {
      alert('発注量は正の数値を入力してください');
      return;
    }

    if (isNaN(quantity)) {
      alert('発注量は数値で入力してください');
      return;
    }

    const product = currentProducts.find(p => p.商品ID === productId);
    if (!product) return;

    // 発注確認モーダル表示
    showOrderConfirmModal([{
      productId,
      productName: product.商品名,
      productCode: product.商品コード,
      quantity,
      reason,
      unitPrice: product.単価 || 0
    }]);
  }

  // 一括発注処理
  function processBulkOrder() {
    const storeId = container.querySelector('#select-store').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const checkedBoxes = container.querySelectorAll('input.product-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    const orderItems = [];
    let hasError = false;

    checkedBoxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);
      const reasonInput = container.querySelector(`input.order-reason[data-product-id="${productId}"]`);
      const product = currentProducts.find(p => p.商品ID === productId);

      const quantity = parseInt(quantityInput?.value) || 0;
      const reason = reasonInput?.value || '';

      if (quantity <= 0 || isNaN(quantity)) {
        alert(`${product?.商品名}: 発注量は正の数値を入力してください`);
        hasError = true;
        return;
      }

      orderItems.push({
        productId,
        productName: product?.商品名,
        productCode: product?.商品コード,
        quantity,
        reason,
        unitPrice: product?.単価 || 0
      });
    });

    if (hasError) return;

    showOrderConfirmModal(orderItems);
  }

  // 発注確認モーダル表示
  function showOrderConfirmModal(orderItems) {
    const modal = container.querySelector('#order-modal');
    const content = container.querySelector('#order-confirm-content');

    const totalAmount = orderItems.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);

    content.innerHTML = `
      <div style="max-height: 300px; overflow-y: auto;">
        <table style="width: 100%; border-collapse: collapse;">
          <thead>
            <tr style="background: var(--bg-main);">
              <th style="padding: 0.5rem; border: 1px solid var(--border);">商品名</th>
              <th style="padding: 0.5rem; border: 1px solid var(--border);">発注量</th>
              <th style="padding: 0.5rem; border: 1px solid var(--border);">単価</th>
              <th style="padding: 0.5rem; border: 1px solid var(--border);">金額</th>
            </tr>
          </thead>
          <tbody>
            ${orderItems.map(item => `
              <tr>
                <td style="padding: 0.5rem; border: 1px solid var(--border);">${item.productName}</td>
                <td style="padding: 0.5rem; border: 1px solid var(--border); text-align: right;">${item.quantity}</td>
                <td style="padding: 0.5rem; border: 1px solid var(--border); text-align: right;">¥${item.unitPrice.toLocaleString()}</td>
                <td style="padding: 0.5rem; border: 1px solid var(--border); text-align: right;">¥${(item.quantity * item.unitPrice).toLocaleString()}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
      <div style="margin-top: 1rem; text-align: right; font-weight: bold;">
        合計金額: ¥${totalAmount.toLocaleString()}
      </div>
    `;

    modal.style.display = 'block';
    modal.dataset.orderItems = JSON.stringify(orderItems);
  }

  // 発注実行
  async function executeOrder() {
    const modal = container.querySelector('#order-modal');
    const orderItems = JSON.parse(modal.dataset.orderItems || '[]');
    const storeId = container.querySelector('#select-store').value;

    try {
      for (const item of orderItems) {
        const orderData = {
          店舗ID: storeId,
          商品ID: item.productId,
          発注日: new Date().toISOString(),
          納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
          発注数量: item.quantity,
          発注単価: item.unitPrice,
          発注金額: item.quantity * item.unitPrice,
          発注方法: '手動発注',
          発注ステータス: '発注済',
          発注理由: item.reason,
          自動発注フラグ: false,
          作成者ID: 'current-user-id',
          更新者ID: 'current-user-id'
        };

        await window.aivicApi.save(ORDER_TABLE, orderData);
      }

      modal.style.display = 'none';
      alert('発注が完了しました');

      // チェックボックスをクリア
      container.querySelectorAll('input.product-checkbox:checked').forEach(cb => cb.checked = false);
      container.querySelector('#select-all').checked = false;

    } catch (error) {
      console.error('発注エラー:', error);
      alert('発注処理でエラーが発生しました');
    }
  }

  // CSVエクスポート
  async function exportCSV() {
    try {
      const products = await window.aivicApi.list(PRODUCT_TABLE) || [];
      const headers = ['商品ID', '商品コード', '商品名', '商品カテゴリID', '単価', '販売価格', '発注単位', '最小発注数量', 'リードタイム日数', '有効フラグ'];

      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...products.map(product => 
          headers.map(header => {
            const value = product[header] || '';
            return typeof value === 'string' && value.includes(',') ? `"${value}"` : value;
          }).join(',')
        )
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `商品一覧_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', searchProducts);
  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);
  container.querySelector('#btn-bulk-order').addEventListener('click', processBulkOrder);
  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    container.querySelector('#order-modal').style.display = 'none';
  });
  container.querySelector('#btn-confirm-order').addEventListener('click', executeOrder);

  // 店舗選択時の自動検索
  container.querySelector('#select-store').addEventListener('change', searchProducts);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('input.product-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 発注量調整ボタン
    const adjustBtn = e.target.closest('.adjust-btn');
    if (adjustBtn) {
      const productId = adjustBtn.dataset.productId;
      const action = adjustBtn.dataset.action;
      adjustOrderQuantity(productId, action);
      return;
    }

    // 個別発注ボタン
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const productId = orderBtn.dataset.productId;
      await processOrder(productId);
      return;
    }
  });

  // 発注量入力のバリデーション
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('order-quantity')) {
      const value = e.target.value;
      if (value && (isNaN(value) || parseInt(value) < 0)) {
        e.target.setCustomValidity('発注量は0以上の数値を入力してください');
      } else {
        e.target.setCustomValidity('');
      }
    }
  });

  // 初期化
  initDropdowns();
}
